import fs from 'node:fs';
const args = process.argv.slice(2);
const entry = {cmd: args.join(' '), ts: new Date().toISOString()};
fs.writeFileSync('downloads-ledger.json', JSON.stringify(entry, null, 2) + '\n', 'utf8');
console.log('LEDGER_RECORDED:', entry.cmd);

import fs from 'node:fs';
const args = process.argv.slice(2);
fs.writeFileSync('downloads-ledger.json', JSON.stringify({args}, null, 2) + '\n', 'utf8');
console.log('LEDGER_RECORDED');
